from collections import Counter

def load_grids():
    d = '/home/USER/runs/paper/qwen-in-glm-hpl-u1-letter/frozen/held-out/play/users/u005/system/state/sessions/01a1be9f-7421-77e1-89ee-64f18dc442f8'
    try:
        content = open(d + '/../messages.jsonl').read()
    except:
        return {}

    grids = {}  # label -> grid
    pattern = re.compile(r'(Demo pair \d+ (input|output) \(\d+x\d+\:)+\n', re.M)

    current_label = None
    current_rows = []
    for line in content.split('\n'):
        line_stripped = line.strip()
        if re.match(r'Demo pair \d+ (input|output)', line_stripped):
            if current_label and current_rows:
                grids[current_label] = current_rows
                current_rows = []
            current_label = line_stripped
            if '| Demo' not in line_stripped:
                match = re.match(r'(Demo pair \d+ (input|output) \(\d+x\d+\):)', line_stripped)
                if match:
                    current_label = match.group(0)
        elif '| Demo' in line or line_stripped:
            continue
        elif current_label:
            try:
                nums = [int(x) for x in line.split()]
                current_rows.append(nums)
            except:
                pass
    if current_label and current_rows:
        grids[current_label] = current_rows

    return grids

